import{c as e,Q as a,j as d,m as r}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"【速報】技術書を Claude Code Skill に変換するツール","description":"","frontmatter":{"url":"https://x.com/sumika45379/status/2065562294374043972","title":"【速報】技術書を Claude Code Skill に変換するツール","author":"すみか@Skillsオタク","archived":"2026-06-15T00:00:00.000Z","category":"deep-application","handle":"@sumika45379","published":"2026-06-12T00:00:00.000Z","score":"7.0/10","stats":"1664❤ · 166 retweets","tags":["claude-code","skills","book-to-skill","knowledge-compilation"],"type":"tweet-thread"},"headers":[],"relativePath":"research/tweets/2026-06-12-@sumika45379-043972.md","filePath":"research/tweets/2026-06-12-@sumika45379-043972.md","lastUpdated":1785909234000}'),l={name:"research/tweets/2026-06-12-@sumika45379-043972.md"};function s(o,t,i,p,n,k){return a(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="【速報】技術書を-claude-code-skill-に変換するツール-—-sumika45379" tabindex="-1">【速報】技術書を Claude Code Skill に変換するツール — @sumika45379 <a class="header-anchor" href="#【速報】技術書を-claude-code-skill-に変換するツール-—-sumika45379" aria-label="Permalink to &quot;【速報】技術書を Claude Code Skill に変換するツール — @sumika45379&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/sumika45379/status/2065562294374043972" target="_blank" rel="noreferrer">https://x.com/sumika45379/status/2065562294374043972</a><strong>類別</strong>：deep-application <strong>統計</strong>：1664❤ · 166 retweets</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>【速報】 技術書をClaude Code Skillに変換するツールが出てた😳 これは見逃したらダメなやつ。</p><p>今まで： 「本を読んで、自分で要点を覚える」</p><p>これから： 「本の概念、workflow、patternsをSkillとしてClaudeに渡す」</p><p>この発想が普通にヤバい。</p><p>・technical bookを入れる ・key conceptsを抽出する ・workflowを整理する ・patternsを再利用可能なAI skillsに変える</p><p>つまり、 「静的な知識」から 「Claudeが実際に使える手順」へ変換するってこと。</p><p>しかも重要なのがここ👇 本って読んだだけだと忘れるじゃん？ でもSkill化すると、Claudeが作業中にその知識を呼び出せる。</p><p>もう 「読んだけど使えない」は普通に損すぎる。</p><p>これは小手先の要約ツールじゃない。 知識をAIの作業手順に変えるための仕組み。</p><p>Claude Skillsをどう作るかを先に理解すると、このBook to Skillの価値がかなり見えやすくなる。 この下の記事を読むと理解が一気に深まる。マジでおすすめ👇😻</p><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>8/10</td><td>書籍→Skills 轉換工具可直接用於擴充 Claude Code Skills 庫</td></tr><tr><td>B. 創新性 (20%)</td><td>9/10</td><td>靜態知識→AI 可執行手順的編譯範式，根本性新思路</td></tr><tr><td>C. 證據品質 (20%)</td><td>5/10</td><td>概念介紹為主，缺乏使用效果的量化佐證</td></tr><tr><td>D. 技術深度 (15%)</td><td>5/10</td><td>工具流程描述清楚，但無實作技術細節</td></tr><tr><td>E. 泛化性 (15%)</td><td>7/10</td><td>書籍知識編譯概念可擴展到任何結構化文件</td></tr><tr><td><strong>加權總分</strong></td><td><strong>7.0/10</strong></td><td>A×0.3+B×0.2+C×0.2+D×0.15+E×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Skill <strong>理由</strong>：書籍→Skills 轉換工具可直接整合進 workspace Skills 建設工作流</p>',18)])])}const h=e(l,[["render",s]]);export{u as __pageData,h as default};
